class Character:
    def __init__(self, name, hp, atk):
        self.name = name
        self.hp = hp
        self.atk = atk

    def attack(self, other):
        other.hp = max(0, other.hp - self.atk)
        print(f"{self.name} → {other.name}: 남은 HP {other.hp}")

    def is_alive(self):
        return self.hp > 0


def read_character():
    name, hp, atk = input().split()
    return Character(name, int(hp), int(atk))


attacker = read_character()
defender = read_character()
turn = 0

while True:
    turn += 1
    attacker.attack(defender)
    if not defender.is_alive():
        print(f"승자: {attacker.name} ({turn}턴)")
        break
    attacker, defender = defender, attacker
